10	    private BreadthFirstTraversal() {
11	    }
12	
13	    public static TraversalResult traverseFrom(Graph graph, int startVertex) {
14	        TraversalState traversalState = TraversalState.create(graph);
15	        graph.requireVertex(startVertex);
16	        traversalState.traverseComponent(startVertex);
17	        return traversalState.result();
18	    }
19	
20	    public static TraversalResult traverseAllComponents(Graph graph) {
21	        TraversalState traversalState = TraversalState.create(graph);
22	
23	        for (int vertex = 0; vertex < graph.vertexCount(); vertex++) {
24	            if (!traversalState.hasVisited(vertex)) {
25	                traversalState.traverseComponent(vertex);
26	            }
27	        }
28	
29	        return traversalState.result();
30	    }
